import{_ as e,o,c as r,a3 as s}from"./chunks/framework.BG5NDHOF.js";const g=JSON.parse(`{"title":"Grille d'évaluation — TP3","description":"","frontmatter":{"title":"Grille d'évaluation — TP3","aside":false},"headers":[],"relativePath":"grilles/grille-tp3.md","filePath":"grilles/grille-tp3.md"}`),d={name:"grilles/grille-tp3.md"};function a(n,t,i,l,c,u){return o(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="grille-d-evaluation-—-travail-pratique-3" tabindex="-1">Grille d&#39;évaluation — Travail Pratique #3 <a class="header-anchor" href="#grille-d-evaluation-—-travail-pratique-3" aria-label="Permalink to &quot;Grille d&#39;évaluation — Travail Pratique #3&quot;">​</a></h1><p>Le TP3 vaut <strong>15 %</strong> : la partie 1 (à la maison) compte pour <strong>10 %</strong>, la partie 2 (en classe, supervisée) pour <strong>5 %</strong>. Chaque partie est notée sur 100, puis ramenée à son poids.</p><p>Chaque question est évaluée selon trois niveaux :</p><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th><th>Note</th></tr></thead><tbody><tr><td><strong>Complet</strong></td><td>L&#39;instruction s&#39;exécute et fait exactement ce qui est demandé : lignes, colonnes, ordre, noms.</td><td>100 %</td></tr><tr><td><strong>Partiel</strong></td><td>La logique est bonne, mais il manque un détail (voir les critères de chaque question).</td><td>60 %</td></tr><tr><td><strong>Nul</strong></td><td>L&#39;instruction ne s&#39;exécute pas, ou ne répond pas à la demande.</td><td>0 %</td></tr></tbody></table><hr><h2 id="partie-1-—-a-la-maison-10" tabindex="-1">Partie 1 — à la maison (10 %) <a class="header-anchor" href="#partie-1-—-a-la-maison-10" aria-label="Permalink to &quot;Partie 1 — à la maison (10 %)&quot;">​</a></h2><h3 id="a-expressions-regulieres-25-points-—-6-25-par-question" tabindex="-1">A. Expressions régulières (25 points — 6,25 par question) <a class="header-anchor" href="#a-expressions-regulieres-25-points-—-6-25-par-question" aria-label="Permalink to &quot;A. Expressions régulières (25 points — 6,25 par question)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Question</th><th>Complet si…</th><th>Exemples de « Partiel »</th></tr></thead><tbody><tr><td><strong>1</strong> Codes non conformes</td><td>Motif ancré (<code>^…$</code>), sensible à la casse (<code>(?-i)</code>), négation correcte.</td><td>Motif non ancré, ou casse ignorée (le code en minuscules passe pour conforme).</td></tr><tr><td><strong>2</strong> Courriels invalides</td><td>Motif ancré, un seul <code>@</code>, extension d&#39;au moins deux lettres, point échappé (<code>\\\\.</code>).</td><td>Point non échappé, extension d&#39;une lettre acceptée, tri absent.</td></tr><tr><td><strong>3</strong> Téléphones nettoyés</td><td>Filtre <code>regexp</code> sur un caractère non numérique; <code>regexp_replace</code> retire tous les séparateurs; alias.</td><td>Un séparateur oublié (espace, parenthèse), filtre absent.</td></tr><tr><td><strong>4</strong> Extraction dans les incidents</td><td>Deux <code>regexp_substr</code> corrects, filtre sur <code>critique</code>, alias, tri.</td><td>Un des deux motifs imprécis (extrait un code malformé, ou <code>SC-</code> non exigé).</td></tr></tbody></table><h3 id="b-jointures-25-points-—-6-25-par-question" tabindex="-1">B. Jointures (25 points — 6,25 par question) <a class="header-anchor" href="#b-jointures-25-points-—-6-25-par-question" aria-label="Permalink to &quot;B. Jointures (25 points — 6,25 par question)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Question</th><th>Complet si…</th><th>Exemples de « Partiel »</th></tr></thead><tbody><tr><td><strong>5</strong> Billets non conformes et revendeur</td><td>Deux jointures correctes, filtre de la question 1 réutilisé, alias de table.</td><td>Colonne manquante, tri absent, alias de colonne <code>nom</code> ambigu.</td></tr><tr><td><strong>6</strong> Programmation du samedi</td><td>Trois tables jointes, intervalle couvrant <strong>toute</strong> la journée.</td><td>Borne d&#39;intervalle qui coupe des spectacles en soirée.</td></tr><tr><td><strong>7</strong> Scans refusés</td><td>Quatre tables jointes; le festivalier est celui <strong>du billet</strong>.</td><td>Colonne ou tri manquant.</td></tr><tr><td><strong>8</strong> Tous les artistes</td><td><code>left join</code> sur <code>spectacle</code> <strong>et</strong> sur <code>scene</code> : les deux artistes sans spectacle apparaissent.</td><td>Le second <code>inner join</code> fait disparaître les artistes sans spectacle.</td></tr></tbody></table><h3 id="c-agregations-et-groupements-25-points-—-6-25-par-question" tabindex="-1">C. Agrégations et groupements (25 points — 6,25 par question) <a class="header-anchor" href="#c-agregations-et-groupements-25-points-—-6-25-par-question" aria-label="Permalink to &quot;C. Agrégations et groupements (25 points — 6,25 par question)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Question</th><th>Complet si…</th><th>Exemples de « Partiel »</th></tr></thead><tbody><tr><td><strong>9</strong> Ventes par revendeur</td><td><code>left join</code>, <code>count(b.id)</code> (0 pour Lumen Billets), <code>sum</code>, <code>round(avg(…), 2)</code>, tri.</td><td><code>count(*)</code> qui donne 1 au revendeur sans vente, ou revendeur absent.</td></tr><tr><td><strong>10</strong> Statistiques par catégorie</td><td>Quatre agrégats, arrondi, tri.</td><td>Arrondi ou alias manquant.</td></tr><tr><td><strong>11</strong> Scènes avec au moins 3 refus</td><td><code>where</code> sur le résultat <strong>avant</strong> le regroupement, <code>having count(*) &gt;= 3</code>.</td><td>Seuil <code>&gt; 3</code>, ou <code>group by</code> incomplet.</td></tr><tr><td><strong>12</strong> Codes en double</td><td><code>group by code</code> et <code>having count(*) &gt; 1</code>.</td><td>Tri ou alias manquant.</td></tr></tbody></table><h3 id="d-sous-requetes-correlees-25-points-—-8-33-par-question" tabindex="-1">D. Sous-requêtes corrélées (25 points — 8,33 par question) <a class="header-anchor" href="#d-sous-requetes-correlees-25-points-—-8-33-par-question" aria-label="Permalink to &quot;D. Sous-requêtes corrélées (25 points — 8,33 par question)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Question</th><th>Complet si…</th><th>Exemples de « Partiel »</th></tr></thead><tbody><tr><td><strong>13</strong> Prix sous 75 % de la moyenne</td><td>Sous-requête corrélée sur la <strong>catégorie</strong>.</td><td>Moyenne de tous les billets (non corrélée) : la logique est fausse → <strong>Nul</strong>.</td></tr><tr><td><strong>14</strong> Jamais acceptés</td><td><code>exists</code> <strong>et</strong> <code>not exists</code>, corrélés sur le festivalier.</td><td>Seulement l&#39;une des deux conditions (inclut les festivaliers jamais scannés).</td></tr><tr><td><strong>15</strong> Codes partagés</td><td><code>exists</code> corrélé sur le code <strong>avec un <code>id</code> différent</strong>.</td><td>Condition sur l&#39;<code>id</code> oubliée : tous les billets sortent → <strong>Nul</strong>.</td></tr></tbody></table><h3 id="conclusion-de-l-enquete" tabindex="-1">Conclusion de l&#39;enquête <a class="header-anchor" href="#conclusion-de-l-enquete" aria-label="Permalink to &quot;Conclusion de l&#39;enquête&quot;">​</a></h3><p>Non notée, mais obligatoire : une conclusion absente entraîne une pénalité de 5 %.</p><hr><h2 id="partie-2-—-en-classe-supervisee-5" tabindex="-1">Partie 2 — en classe, supervisée (5 %) <a class="header-anchor" href="#partie-2-—-en-classe-supervisee-5" aria-label="Permalink to &quot;Partie 2 — en classe, supervisée (5 %)&quot;">​</a></h2><p>Les instructions doivent s&#39;exécuter <strong>dans l&#39;ordre</strong>. Une instruction qui échoue à cause d&#39;une question précédente ratée n&#39;est pas pénalisée deux fois : on corrige la logique de chaque réponse.</p><h3 id="a-modifier-la-structure-20-points-—-5-par-question" tabindex="-1">A. Modifier la structure (20 points — 5 par question) <a class="header-anchor" href="#a-modifier-la-structure-20-points-—-5-par-question" aria-label="Permalink to &quot;A. Modifier la structure (20 points — 5 par question)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Question</th><th>Complet si…</th><th>Exemples de « Partiel »</th></tr></thead><tbody><tr><td><strong>1</strong> Colonne <code>actif</code></td><td><code>alter table … add column</code>, <code>not null</code>, <code>default true</code>.</td><td><code>not null</code> ou <code>default</code> manquant.</td></tr><tr><td><strong>2</strong> Désactiver Billets Éclair</td><td><code>update</code> filtré sur le nom, une seule ligne.</td><td>—</td></tr><tr><td><strong>3</strong> Agrandir le courriel</td><td><code>modify column … varchar(150) not null</code>.</td><td><code>not null</code> perdu (la colonne devient nullable).</td></tr><tr><td><strong>4</strong> Renommer <code>duree</code></td><td><code>rename column</code> ou <code>change column</code> avec le type complet.</td><td><code>change column</code> sans <code>not null</code>.</td></tr></tbody></table><h3 id="b-nettoyer-et-verrouiller-les-billets-35-points-—-7-par-question" tabindex="-1">B. Nettoyer et verrouiller les billets (35 points — 7 par question) <a class="header-anchor" href="#b-nettoyer-et-verrouiller-les-billets-35-points-—-7-par-question" aria-label="Permalink to &quot;B. Nettoyer et verrouiller les billets (35 points — 7 par question)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Question</th><th>Complet si…</th><th>Exemples de « Partiel »</th></tr></thead><tbody><tr><td><strong>5</strong> Cascade</td><td><code>drop foreign key scan_billet_fk</code> puis <code>add constraint scan_billet_fk … on delete cascade</code>.</td><td>Nom différent, ou <code>on update cascade</code> au lieu de <code>on delete</code>.</td></tr><tr><td><strong>6</strong> Supprimer les billets d&#39;Éclair</td><td><code>delete</code> avec une sous-requête sur le nom du revendeur : 13 billets.</td><td><code>id</code> codé en dur.</td></tr><tr><td><strong>7</strong> Unicité du code</td><td><code>add constraint billet_code_uq unique (code)</code>.</td><td>Nom inexact.</td></tr><tr><td><strong>8</strong> Format du code</td><td><code>check</code> avec <code>regexp</code>, motif ancré et <code>(?-i)</code>, nom exact.</td><td>Casse non exigée, motif non ancré, nom inexact.</td></tr><tr><td><strong>9</strong> Index</td><td><code>create index scan_date_heure_idx on scan (date_heure)</code>.</td><td>Nom inexact.</td></tr></tbody></table><h3 id="c-mots-de-passe-20-points-—-10-par-question" tabindex="-1">C. Mots de passe (20 points — 10 par question) <a class="header-anchor" href="#c-mots-de-passe-20-points-—-10-par-question" aria-label="Permalink to &quot;C. Mots de passe (20 points — 10 par question)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Question</th><th>Complet si…</th><th>Exemples de « Partiel »</th></tr></thead><tbody><tr><td><strong>10</strong> Hachage</td><td>Deux colonnes ajoutées, sel par revendeur, <code>sha2(concat(sel, mot_de_passe), 256)</code>, colonne en clair supprimée.</td><td>Hachage sans sel, ou colonne en clair conservée.</td></tr><tr><td><strong>11</strong> Vérification</td><td>Le hachage est recalculé <strong>avec le sel de la ligne</strong> et comparé : 1 ligne.</td><td>Mot de passe comparé en clair → <strong>Nul</strong>.</td></tr></tbody></table><h3 id="d-comptes-et-privileges-25-points-—-6-25-par-question" tabindex="-1">D. Comptes et privilèges (25 points — 6,25 par question) <a class="header-anchor" href="#d-comptes-et-privileges-25-points-—-6-25-par-question" aria-label="Permalink to &quot;D. Comptes et privilèges (25 points — 6,25 par question)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Question</th><th>Complet si…</th><th>Exemples de « Partiel »</th></tr></thead><tbody><tr><td><strong>12</strong> <code>analyste</code></td><td><code>create user &#39;analyste&#39;@&#39;localhost&#39;</code>, <code>grant select on festival_boreal.*</code>.</td><td>Hôte manquant (<code>&#39;analyste&#39;@&#39;%&#39;</code>).</td></tr><tr><td><strong>13</strong> <code>agent_acces</code></td><td>Privilèges <strong>par table</strong> : <code>select</code> sur <code>billet</code>, <code>select, insert</code> sur <code>scan</code>.</td><td>Droits accordés sur toute la base.</td></tr><tr><td><strong>14</strong> <code>admin_festival</code></td><td><code>grant all privileges on festival_boreal.*</code>.</td><td><code>on *.*</code> (tout le serveur) → <strong>Nul</strong> : contraire au moindre privilège.</td></tr><tr><td><strong>15</strong> Retrait et vérification</td><td><code>revoke insert on festival_boreal.scan</code>, puis <code>show grants for &#39;agent_acces&#39;@&#39;localhost&#39;</code>.</td><td><code>show grants</code> manquant.</td></tr></tbody></table><hr><h2 id="penalites-—-respect-des-consignes" tabindex="-1">Pénalités — Respect des consignes <a class="header-anchor" href="#penalites-—-respect-des-consignes" aria-label="Permalink to &quot;Pénalités — Respect des consignes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Cas</th><th>Impact</th></tr></thead><tbody><tr><td>Retard dans la remise de la partie 1</td><td>−10 % par jour (maximum −30 %)</td></tr><tr><td>Fichier de réponses non utilisé, ou ordre des requêtes modifié</td><td>−5 %</td></tr><tr><td>Notion non vue au cours, sans validation de l&#39;enseignant</td><td>−5 % par occurrence (maximum −30 %)</td></tr><tr><td>Utilisation non autorisée d&#39;une source externe ou plagiat</td><td>0 % au travail</td></tr></tbody></table>',30)])])}const h=e(d,[["render",a]]);export{g as __pageData,h as default};
